// Exact API67 fixture populations admitted in Waves25c and28.
func TestRunCompressionNativeProofs(t *testing.T) {
	t.Run("indexed_entries", func(t *testing.T) {
		root := t.TempDir()
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeCompressionProof67.cls"), "@IsTest private class GladeCompressionProof67 {\nprivate static String central(Blob archive) {String bytes=EncodingUtil.convertToHex(archive).toLowerCase();Integer offset=bytes.indexOf('504b0102');System.assert(offset>=0,'Expected ZIP central directory');return bytes.substring(offset);}\n@IsTest static void independentStoredBytesAndMetadata() { Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));Compression.ZipEntry e=r.getEntry('stored.bin');System.assertEquals('stored.bin',e.getName());System.assertEquals('owned stored comment',e.getComment());System.assertEquals(Compression.Method.STORED,e.getMethod());System.assertEquals(6L,e.getCompressedSize());System.assertEquals(6L,e.getUncompressedSize());System.assertEquals(4210012891L,e.getCrc());System.assertEquals(Datetime.newInstanceGMT(2024,2,3,4,5,6),e.getLastModifiedTime());System.assertEquals('000102ff415a',EncodingUtil.convertToHex(r.extract('stored.bin')).toLowerCase());System.assertEquals('000102ff415a',EncodingUtil.convertToHex(r.extract(e)).toLowerCase()); }\n@IsTest static void independentDeflateAndUnicode() { Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));Compression.ZipEntry e=r.getEntry('unicodé/雪.txt');System.assertEquals(Compression.Method.DEFLATED,e.getMethod());System.assertEquals(18L,e.getCompressedSize());System.assertEquals(352L,e.getUncompressedSize());System.assertEquals(3277694539L,e.getCrc());System.assertEquals('Héllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\nHéllo\\n雪\\n',r.extract(e).toString()); }\n@IsTest static void independentEmptyAndCaseDistinctNames() { Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));System.assertEquals(4,r.getEntries().size());System.assertEquals(4,r.getEntriesMap().size());System.assertEquals(5,r.getEntryNames().size());System.assertEquals('Case.txt',r.getEntryNames().get(3));System.assertEquals('case.txt',r.getEntryNames().get(4));System.assertEquals('UPPER',r.extract('Case.txt').toString());System.assertEquals(null,r.getEntry('case.txt'));System.assertEquals(null,r.getEntry('CASE.TXT'));for(String name:new List<String>{'case.txt','CASE.TXT'}){Boolean caught=false;try{r.extract(name);}catch(Exception e){caught=true;System.assertEquals('System.NullPointerException',e.getTypeName());System.assertEquals('Attempt to de-reference a null object',e.getMessage());}System.assertEquals(true,caught,name);}System.assertEquals(0,r.extract('empty').size());System.assertEquals(0L,r.getEntry('empty').getCrc()); }\n@IsTest static void writerStoredOptionChangesArchiveBytes() { Compression.ZipWriter w=new Compression.ZipWriter();w.setMethod(Compression.Method.STORED);w.addEntry('stored.bin',EncodingUtil.convertFromHex('000102ff415a'));Blob zip=w.getArchive();String hex=EncodingUtil.convertToHex(zip).toLowerCase();System.assertEquals('504b0304',hex.substring(0,8));System.assertEquals('0000',hex.substring(16,20));String directory=central(zip);System.assertEquals('0000',directory.substring(20,24));System.assertEquals('dbb2effa',directory.substring(32,40));System.assertEquals('06000000',directory.substring(40,48));System.assertEquals('06000000',directory.substring(48,56)); }\n@IsTest static void writerExplicitEntryMetadataSurvives() { Compression.ZipWriter w=new Compression.ZipWriter();Compression.ZipEntry e=w.addEntry('stored.bin','owned stored comment',Datetime.newInstanceGMT(2024,2,3,4,5,6),Compression.Method.STORED,EncodingUtil.convertFromHex('000102ff415a'));System.assertEquals('000102ff415a',EncodingUtil.convertToHex(e.getContent()).toLowerCase());Compression.ZipReader r=new Compression.ZipReader(w.getArchive());System.assertEquals('owned stored comment',r.getEntry('stored.bin').getComment());System.assertEquals(Datetime.newInstanceGMT(2024,2,3,4,5,6),r.getEntry('stored.bin').getLastModifiedTime());System.assertEquals(Compression.Method.STORED,r.getEntry('stored.bin').getMethod());System.assertEquals(4210012891L,r.getEntry('stored.bin').getCrc()); }\n@IsTest static void compressionLevelChangesPhysicalSize() { Blob data=Blob.valueOf('');Compression.ZipWriter plain=new Compression.ZipWriter();plain.setMethod(Compression.Method.DEFLATED);plain.setLevel(Compression.Level.NO_COMPRESSION);plain.addEntry('owned.txt',data);Compression.ZipWriter best=new Compression.ZipWriter();best.setMethod(Compression.Method.DEFLATED);best.setLevel(Compression.Level.BEST_COMPRESSION);best.addEntry('owned.txt',data);Blob a=plain.getArchive();Blob b=best.getArchive();System.assert(a.size()>b.size(),'NO_COMPRESSION must not compress this repeated payload');System.assertEquals('0800',central(a).substring(20,24));System.assertEquals('0800',central(b).substring(20,24));System.assertEquals('1afb37b7',central(a).substring(32,40));System.assertEquals('1afb37b7',central(b).substring(32,40)); }\n@IsTest static void prototypeCopyHasIndependentMutableState() { Compression.ZipWriter original=new Compression.ZipWriter();Compression.ZipEntry source=original.addEntry('copy.txt','before',Datetime.newInstanceGMT(2024,2,3,4,5,6),Compression.Method.STORED,Blob.valueOf('original'));Compression.ZipWriter destination=new Compression.ZipWriter();Compression.ZipEntry copy=destination.addEntry(source);source.setComment('changed');source.setContent(Blob.valueOf('changed'));source.setLastModifiedTime(Datetime.newInstanceGMT(2025,1,1,0,0,0));System.assertEquals('before',copy.getComment());System.assertEquals('original',copy.getContent().toString());System.assertEquals(Datetime.newInstanceGMT(2024,2,3,4,5,6),copy.getLastModifiedTime());System.assertEquals('original',new Compression.ZipReader(destination.getArchive()).extract('copy.txt').toString());System.assertEquals('changed',source.getContent().toString()); }\n}\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeCompressionProof67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
		writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\":\"67.0\",\"packageDirectories\":[{\"path\":\"force-app\",\"default\":true}]}")
		run := Run(loadTestIndex(t, root), Options{})
		if got := run.Summary(); got.Total != 7 || got.Passed != 7 || got.Skipped != 0 {
			data, _ := json.Marshal(run)
			t.Fatalf("exact native ZIP proof failed: %s", data)
		}
	})
	t.Run("native_membership", func(t *testing.T) {
		root := t.TempDir()
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeZipMembershipExact67.cls"), "@IsTest private class GladeZipMembershipExact67 {@IsTest static void nativeMembershipDiffersFromIndexedStrings(){Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));List<String> names=r.getEntryNames();System.assertEquals(5,names.size());for(String expected:new List<String>{'stored.bin','Case.txt','case.txt','CASE.TXT'}){System.assertEquals(false,names.contains(expected));System.assertEquals(false,r.getEntryNames().contains(expected));System.assertEquals(-1,names.indexOf(expected));}System.assertEquals(true,names.get(0).equals('stored.bin'));System.assertEquals(true,names.get(3).equals('Case.txt'));System.assertEquals(true,names.get(4).equals('case.txt'));}}\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeZipMembershipExact67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
		writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\":\"67.0\",\"packageDirectories\":[{\"path\":\"force-app\",\"default\":true}]}")
		run := Run(loadTestIndex(t, root), Options{})
		if got := run.Summary(); got.Total != 1 || got.Passed != 1 || got.Skipped != 0 {
			data, _ := json.Marshal(run)
			t.Fatalf("exact native ZIP proof failed: %s", data)
		}
	})
	t.Run("native_copy", func(t *testing.T) {
		root := t.TempDir()
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeZipCopyExact67.cls"), "@IsTest private class GladeZipCopyExact67 {private static void record(List<Object> rows,String name,List<String> values){rows.add(new Map<String,Object>{'n'=>name,'size'=>values.size(),'first'=>values.isEmpty()?null:values.get(0),'contains'=>values.contains('stored.bin'),'indexOf'=>values.indexOf('stored.bin')});}private static void error(List<Object> rows,String name,Exception e){rows.add(new Map<String,Object>{'n'=>name,'type'=>e.getTypeName(),'message'=>e.getMessage().left(180)});}@IsTest static void observeCopyAndMutation(){Compression.ZipReader r=new Compression.ZipReader(EncodingUtil.base64Decode(''));List<String> names=r.getEntryNames();List<Object> rows=new List<Object>();record(rows,'native',names);try{record(rows,'clone',names.clone());}catch(Exception e){error(rows,'clone',e);}try{record(rows,'constructor',new List<String>(names));}catch(Exception e){error(rows,'constructor',e);}try{List<String> values=new List<String>();values.addAll(names);record(rows,'addAll',values);}catch(Exception e){error(rows,'addAll',e);}try{List<String> values=new List<String>();for(String name:names)values.add(name);record(rows,'manual',values);}catch(Exception e){error(rows,'manual',e);}try{names.add('owned-added');rows.add(new Map<String,Object>{'n'=>'mutation','size'=>names.size(),'containsAdded'=>names.contains('owned-added'),'indexOfAdded'=>names.indexOf('owned-added'),'freshSize'=>r.getEntryNames().size(),'freshContainsAdded'=>r.getEntryNames().contains('owned-added')});}catch(Exception e){error(rows,'mutation',e);}String message=JSON.serialize(rows);System.assert(message.length()<=3000,'Owned observer exceeded bound');verify(rows);}\nprivate static void verify(List<Object> rows){List<Object> expected=(List<Object>)JSON.deserializeUntyped('[{\"indexOf\":-1,\"contains\":false,\"first\":\"stored.bin\",\"size\":5,\"n\":\"native\"},{\"indexOf\":-1,\"contains\":false,\"first\":\"stored.bin\",\"size\":5,\"n\":\"clone\"},{\"indexOf\":0,\"contains\":true,\"first\":\"stored.bin\",\"size\":5,\"n\":\"constructor\"},{\"indexOf\":0,\"contains\":true,\"first\":\"stored.bin\",\"size\":5,\"n\":\"addAll\"},{\"indexOf\":0,\"contains\":true,\"first\":\"stored.bin\",\"size\":5,\"n\":\"manual\"},{\"freshContainsAdded\":false,\"freshSize\":5,\"indexOfAdded\":5,\"containsAdded\":true,\"size\":6,\"n\":\"mutation\"}]');System.assertEquals(6,rows.size());for(Integer i=0;i<6;i++){Map<String,Object> want=(Map<String,Object>)expected[i];Map<String,Object> got=(Map<String,Object>)rows[i];System.assertEquals(want.keySet(),got.keySet());for(String key:want.keySet())System.assertEquals(want.get(key),got.get(key),String.valueOf(i)+':'+key);}}\n}\n")
		writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeZipCopyExact67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
		writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\":\"67.0\",\"packageDirectories\":[{\"path\":\"force-app\",\"default\":true}]}")
		run := Run(loadTestIndex(t, root), Options{})
		if got := run.Summary(); got.Total != 1 || got.Passed != 1 || got.Skipped != 0 {
			data, _ := json.Marshal(run)
			t.Fatalf("exact native ZIP proof failed: %s", data)
		}
	})
}

// Exact API67 four-method population admitted in Wave32.
func TestRunCompressionNativeAdjacentProofs(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeZipNativeAdjacentExact67.cls"), "@IsTest private class GladeZipNativeAdjacentExact67 {\nprivate static List<String> names(){return new Compression.ZipReader(EncodingUtil.base64Decode('')).getEntryNames();}\n\nprivate static void error(List<Object> rows,String label,Exception e){rows.add(new Map<String,Object>{'n'=>label,'t'=>e.getTypeName()});}\nprivate static void done(List<Object> rows,String label){rows.add(new Map<String,Object>{'n'=>label,'ok'=>true});}\nprivate static void probe(List<Object> rows,String label,List<String> values,String needle){Map<String,Object> row=new Map<String,Object>{'n'=>label};try{row.put('contains',values.contains(needle));}catch(Exception e){row.put('containsError',e.getTypeName());}try{row.put('indexOf',values.indexOf(needle));}catch(Exception e){row.put('indexError',e.getTypeName());}try{List<String> observed=new List<String>();for(Integer i=0;i<values.size();i++)observed.add(values.get(i));row.put('values',observed);}catch(Exception e){row.put('valuesError',e.getTypeName());}rows.add(row);}\nprivate static void probeIndex(List<Object> rows,String label,List<String> values,Integer index){try{probe(rows,label,values,values.get(index));}catch(Exception e){error(rows,label,e);}}\nprivate static void verify(List<Object> rows,String method){String encoded;\nif(method=='copyCloneChains'){encoded='[{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":-1,\"contains\":false,\"n\":\"nativeClone\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":0,\"contains\":true,\"n\":\"constructorAfterClone\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":0,\"contains\":true,\"n\":\"cloneAfterConstructor\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":-1,\"contains\":false,\"n\":\"doubleClone\"},{\"ok\":true,\"n\":\"cloneAppendOrdinary\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\",\"stored.bin\"],\"indexOf\":5,\"contains\":true,\"n\":\"mutatedClone\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\",\"stored.bin\"],\"indexOf\":0,\"contains\":true,\"n\":\"constructorCloneAfterMutation\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":-1,\"contains\":false,\"n\":\"originalAfterCloneMutation\"}]';}\nelse if(method=='indexedMutations'){encoded='[{\"ok\":true,\"n\":\"insertOrdinary\"},{\"values\":[\"stored.bin\",\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":0,\"contains\":true,\"n\":\"insertIndexed\"},{\"values\":[\"stored.bin\",\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":0,\"contains\":true,\"n\":\"insertLiteral\"},{\"value\":\"stored.bin\",\"n\":\"removeNative\"},{\"values\":[\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":-1,\"contains\":false,\"n\":\"removedNeedle\"},{\"ok\":true,\"n\":\"setOrdinary\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":0,\"contains\":true,\"n\":\"setIndexed\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":0,\"contains\":true,\"n\":\"setLiteral\"}]';}\nelse if(method=='indexedValueNeedles'){encoded='[{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":-1,\"contains\":false,\"n\":\"self0\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":-1,\"contains\":false,\"n\":\"self3\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":-1,\"contains\":false,\"n\":\"self4\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":-1,\"contains\":false,\"n\":\"literal0\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":-1,\"contains\":false,\"n\":\"literalCase\"}]';}\nelse if(method=='nativeAppendAndDuplicates'){encoded='[{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":-1,\"contains\":false,\"n\":\"initial\"},{\"ok\":true,\"n\":\"appendNative\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\",\"stored.bin\"],\"indexOf\":5,\"contains\":true,\"n\":\"nativeAppendLiteral\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\",\"stored.bin\"],\"indexOf\":5,\"contains\":true,\"n\":\"nativeAppendIndexed\"},{\"ok\":true,\"n\":\"appendOrdinaryDuplicate\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\",\"stored.bin\",\"stored.bin\"],\"indexOf\":5,\"contains\":true,\"n\":\"ordinaryDuplicateLiteral\"},{\"ok\":true,\"n\":\"nativeAddAll\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\",\"stored.bin\",\"stored.bin\",\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":5,\"contains\":true,\"n\":\"addAllIndexedNeedle\"},{\"values\":[\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\",\"stored.bin\",\"stored.bin\",\"stored.bin\",\"unicodé/雪.txt\",\"empty\",\"Case.txt\",\"case.txt\"],\"indexOf\":5,\"contains\":true,\"n\":\"addAllLiteralNeedle\"}]';}\nelse{System.assert(false,'Unknown exact method '+method);return;}\nList<Object> expected=(List<Object>)JSON.deserializeUntyped(encoded);System.assertEquals(expected.size(),rows.size(),'Every observed row');for(Integer i=0;i<expected.size();i++){Map<String,Object> want=(Map<String,Object>)expected[i];Map<String,Object> got=(Map<String,Object>)rows[i];System.assertEquals(want.keySet(),got.keySet(),method+':keys:'+i);for(String key:want.keySet()){System.assertEquals(want.get(key),got.get(key),method+':'+i+':'+key);}}}\n@IsTest static void indexedValueNeedles(){List<Object> rows=new List<Object>();List<String> values=names();probeIndex(rows,'self0',values,0);probeIndex(rows,'self3',values,3);probeIndex(rows,'self4',values,4);probe(rows,'literal0',values,'stored.bin');probe(rows,'literalCase',values,'Case.txt');verify(rows,'indexedValueNeedles');}\n@IsTest static void nativeAppendAndDuplicates(){List<Object> rows=new List<Object>();List<String> values=names();List<String> other=names();probe(rows,'initial',values,'stored.bin');try{values.add(other.get(0));done(rows,'appendNative');}catch(Exception e){error(rows,'appendNative',e);}probe(rows,'nativeAppendLiteral',values,'stored.bin');probeIndex(rows,'nativeAppendIndexed',values,0);try{values.add('stored.bin');done(rows,'appendOrdinaryDuplicate');}catch(Exception e){error(rows,'appendOrdinaryDuplicate',e);}probe(rows,'ordinaryDuplicateLiteral',values,'stored.bin');try{values.addAll(other);done(rows,'nativeAddAll');}catch(Exception e){error(rows,'nativeAddAll',e);}try{probe(rows,'addAllIndexedNeedle',values,other.get(0));}catch(Exception e){error(rows,'addAllIndexedNeedle',e);}probe(rows,'addAllLiteralNeedle',values,'stored.bin');verify(rows,'nativeAppendAndDuplicates');}\n@IsTest static void indexedMutations(){List<Object> rows=new List<Object>();List<String> inserted=names();try{inserted.add(0,'stored.bin');done(rows,'insertOrdinary');}catch(Exception e){error(rows,'insertOrdinary',e);}probeIndex(rows,'insertIndexed',inserted,0);probe(rows,'insertLiteral',inserted,'stored.bin');List<String> removed=names();String extracted;try{extracted=removed.remove(0);rows.add(new Map<String,Object>{'n'=>'removeNative','value'=>extracted});}catch(Exception e){error(rows,'removeNative',e);}probe(rows,'removedNeedle',removed,extracted);List<String> replaced=names();try{replaced.set(0,'stored.bin');done(rows,'setOrdinary');}catch(Exception e){error(rows,'setOrdinary',e);}probeIndex(rows,'setIndexed',replaced,0);probe(rows,'setLiteral',replaced,'stored.bin');verify(rows,'indexedMutations');}\n@IsTest static void copyCloneChains(){List<Object> rows=new List<Object>();List<String> values=names();List<String> copied;try{copied=values.clone();probe(rows,'nativeClone',copied,'stored.bin');}catch(Exception e){error(rows,'nativeClone',e);}try{probe(rows,'constructorAfterClone',new List<String>(values.clone()),'stored.bin');}catch(Exception e){error(rows,'constructorAfterClone',e);}try{probe(rows,'cloneAfterConstructor',new List<String>(values).clone(),'stored.bin');}catch(Exception e){error(rows,'cloneAfterConstructor',e);}try{probe(rows,'doubleClone',values.clone().clone(),'stored.bin');}catch(Exception e){error(rows,'doubleClone',e);}try{copied.add('stored.bin');done(rows,'cloneAppendOrdinary');}catch(Exception e){error(rows,'cloneAppendOrdinary',e);}probe(rows,'mutatedClone',copied,'stored.bin');try{probe(rows,'constructorCloneAfterMutation',new List<String>(copied).clone(),'stored.bin');}catch(Exception e){error(rows,'constructorCloneAfterMutation',e);}probe(rows,'originalAfterCloneMutation',values,'stored.bin');verify(rows,'copyCloneChains');}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeZipNativeAdjacentExact67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\":\"67.0\",\"packageDirectories\":[{\"path\":\"force-app\",\"default\":true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 4 || got.Passed != 4 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("exact native ZIP adjacent proof failed: %s", data)
	}
}
